"use client";

import { Dialog as SheetPrimitive } from "@base-ui/react/dialog";
import { cn } from "cn";
import { XIcon } from "lucide-react";
import type * as React from "react";
import { Button } from "@/components/ui/button";

// Design.md §3.10: one sheet for every detail and editor, from the right.
// Generated by shadcn (base-nova) and changed in two places: the popup slides
// fully in over 600 ms with a soft ease-out and out over 300 ms with ease-in,
// replacing the short nudge and fade; and it comes in two sizes. Reduced
// motion needs nothing here: the reduced-motion block in globals.css cuts
// every transition to nothing, so the sheet appears without movement.
//
// Base UI's dialog keeps key events from reaching `window`, so a sheet's own
// shortcuts go on `SheetContent` as `onKeyDown`, never on the window.

const SHEET_SIZES = {
  /** Journal detail, compare. */
  wide: "lg:max-w-5xl",
  /** Editors, the firm page. */
  medium: "lg:max-w-2xl",
} as const;

function Sheet({ ...props }: SheetPrimitive.Root.Props) {
  return <SheetPrimitive.Root data-slot="sheet" {...props} />;
}

function SheetTrigger({ ...props }: SheetPrimitive.Trigger.Props) {
  return <SheetPrimitive.Trigger data-slot="sheet-trigger" {...props} />;
}

function SheetClose({ ...props }: SheetPrimitive.Close.Props) {
  return <SheetPrimitive.Close data-slot="sheet-close" {...props} />;
}

function SheetPortal({ ...props }: SheetPrimitive.Portal.Props) {
  return <SheetPrimitive.Portal data-slot="sheet-portal" {...props} />;
}

function SheetOverlay({ className, ...props }: SheetPrimitive.Backdrop.Props) {
  return (
    <SheetPrimitive.Backdrop
      data-slot="sheet-overlay"
      className={cn(
        "fixed inset-0 z-50 bg-black/40 transition-opacity duration-300 data-ending-style:opacity-0 data-starting-style:opacity-0",
        className,
      )}
      {...props}
    />
  );
}

function SheetContent({
  className,
  children,
  size = "medium",
  showCloseButton = true,
  ...props
}: SheetPrimitive.Popup.Props & {
  size?: keyof typeof SHEET_SIZES;
  showCloseButton?: boolean;
}) {
  return (
    <SheetPortal>
      <SheetOverlay />
      <SheetPrimitive.Popup
        data-slot="sheet-content"
        data-size={size}
        className={cn(
          // Below `lg` the sheet takes the full width (Design.md §3.12).
          // Tailwind drives `translate-x-*` through `translate`, so that is
          // the property the transition names (coding-standards.md, Motion).
          "fixed inset-y-0 right-0 z-50 flex h-full w-full flex-col overflow-y-auto border-l bg-popover text-popover-foreground text-sm shadow-lg outline-none transition-[translate] duration-[600ms] ease-[cubic-bezier(0.32,0.72,0,1)] data-ending-style:translate-x-full data-ending-style:duration-300 data-ending-style:ease-in data-starting-style:translate-x-full",
          SHEET_SIZES[size],
          className,
        )}
        {...props}
      >
        {children}
        {showCloseButton && (
          <SheetPrimitive.Close
            data-slot="sheet-close"
            render={
              <Button
                variant="ghost"
                className="absolute top-3 right-3 size-10"
                size="icon-lg"
              />
            }
          >
            <XIcon />
            <span className="sr-only">Close</span>
          </SheetPrimitive.Close>
        )}
      </SheetPrimitive.Popup>
    </SheetPortal>
  );
}

function SheetHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sheet-header"
      className={cn("flex flex-col gap-0.5 p-4", className)}
      {...props}
    />
  );
}

function SheetFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sheet-footer"
      className={cn("mt-auto flex flex-col gap-2 p-4", className)}
      {...props}
    />
  );
}

function SheetTitle({ className, ...props }: SheetPrimitive.Title.Props) {
  return (
    <SheetPrimitive.Title
      data-slot="sheet-title"
      className={cn("font-medium text-base text-foreground", className)}
      {...props}
    />
  );
}

function SheetDescription({
  className,
  ...props
}: SheetPrimitive.Description.Props) {
  return (
    <SheetPrimitive.Description
      data-slot="sheet-description"
      className={cn("text-muted-foreground text-sm", className)}
      {...props}
    />
  );
}

export {
  Sheet,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
};
